//! A lab's generated files kept readable across an update of the launcher: a run manifest on
//! disk is the version of the Isoloom that wrote it, and the runner reads one version only. A lab
//! generated by an earlier launcher (a lab left running, or parked, across the update) has its
//! files generated again for the same target before any operation opens its manifest, so it can
//! still be stopped, parked, checked, read and handed over. Generation is deterministic: the lab's
//! spec, its instance (`.isoloom-<n>/`) and the launcher's overrides give the same files the new
//! version would have written at the lab's start.
//!
//! One form is never generated again: a container lab an earlier version ran inside one helper VM
//! (Isoloom's former `docker-vm`), which Isoloom no longer generates. Such a run is read as it
//! is, so it can still be stopped and removed; when its manifest isn't readable any more, the lab
//! is moved to its true form instead ([`in_true_form`]).

use std::path::{Path, PathBuf};
use std::sync::Arc;

use tokio::sync::Mutex as AsyncMutex;

use isoloom_manifest::ManifestVersion;

use super::errors::{ADD_AGAIN, EARLIER_FILES};
use crate::error::{Error, Result};
use crate::platform::sync::KeyedLocks;
use crate::runtime::lab;

/// The lock of the lab in `dir`, held while its manifest's version is read and, when it isn't this
/// build's, its files are generated again: an operation reading the manifest meanwhile (a status
/// the lab page asks for during a stop) never reads a file half written. One per lab: another
/// lab's status read never waits on this one's generation (several seconds for a large lab). An
/// async lock: a read waiting on it gives its thread back meanwhile.
fn lab_lock(dir: &Path) -> Arc<AsyncMutex<()>> {
    static LOCKS: KeyedLocks<PathBuf> = KeyedLocks::new();
    LOCKS.get(dir)
}

/// Generates the files of the lab in `dir` for `target` again when its run manifest, `manifest`,
/// isn't the version this build reads; nothing when it is, or when there is none (no files yet)
/// or it isn't one at all (the runner says what is wrong with it). No `target`: the manifest is a
/// helper VM's an earlier version left, which is read as it is while this build reads its
/// version, and otherwise moved to the lab's true form ([`in_true_form`]). The generation (seconds
/// for a large lab) runs on a blocking thread, off the async workers a status read runs on.
///
/// # Errors
///
/// When the lab's files can't be generated any more (its spec gone or unreadable, the lab no
/// longer able to run there, or the form it ran in gone), saying what to do.
pub(super) async fn current(manifest: &Path, dir: &Path, target: Option<lab::Target>) -> Result<()> {
    let lock = lab_lock(dir);
    let _held = lock.lock().await;
    let Some(found) = stale_version(manifest) else { return Ok(()) };
    let Some(target) = target else { return Err(in_true_form(manifest, dir, &found).await) };
    log::info!("{}: its run manifest is version {found}, which this version doesn't read; generating the lab's files again", manifest.display());
    generate(dir, target).await.map_err(|e| Error::Invalid(format!("{EARLIER_FILES}: {e}. {ADD_AGAIN}")))
}

/// Generates the lab in `dir` for `target`, on a blocking thread.
async fn generate(dir: &Path, target: lab::Target) -> Result<()> {
    let dir = dir.to_path_buf();
    crate::platform::off_runtime(move || lab::prepare(&dir, target).map(drop)).await
}

/// A container lab's true form, for one an earlier version ran inside a helper VM: its containers
/// on this machine's Docker when Docker answers (`docker`), else its machines as VMs.
pub(super) fn true_form(docker: bool) -> lab::Target {
    if docker { lab::Target::Docker } else { lab::Target::Vagrant }
}

/// The lab in `dir` ran in a helper VM whose run manifest (`manifest`, version `found`) this
/// build doesn't read, and Isoloom no longer generates that form, so it can't be made again: the
/// lab's files are generated in its true form instead ([`true_form`]) and its helper-VM mark is
/// cleared, so its next start runs that form, as the log says. The error says what is left of the
/// old run, which nothing here reaches any more.
async fn in_true_form(manifest: &Path, dir: &Path, found: &serde_json::Value) -> Error {
    let form = true_form(crate::runtime::docker::answers().await);
    log::warn!(
        "{}: its run manifest is version {found}, which this version doesn't read, and it ran Docker inside a helper VM (docker-vm), which Isoloom no longer generates: generating the lab's files as {} instead",
        manifest.display(),
        form.id()
    );
    match generate(dir, form).await.and_then(|()| crate::runtime::paths::mark_local_vm(dir, None)) {
        Ok(()) => log::info!("{}: the lab now starts as {}", dir.display(), form.id()),
        Err(e) => log::warn!("{}: its files couldn't be generated as {}: {e}", dir.display(), form.id()),
    }
    Error::Invalid(format!("{EARLIER_FILES}: it ran Docker inside a VM, which this version no longer does. {ADD_AGAIN}"))
}

/// The Isoloom target whose files hold a run manifest of `target` (what the runner records of a
/// run); none for a helper VM's (`docker-vm`), whose files Isoloom no longer generates.
pub(super) fn lab_target(target: isoloom_manifest::Target) -> Option<lab::Target> {
    use isoloom_manifest::Target as Run;
    Some(match target {
        Run::Docker => lab::Target::Docker,
        Run::DockerVm => return None,
        Run::Vagrant => lab::Target::Vagrant,
        Run::Proxmox => lab::Target::Proxmox,
        Run::Esxi => lab::Target::Esxi,
        Run::CloudDocker => lab::Target::CloudDocker,
        Run::CloudVm => lab::Target::CloudVm,
        Run::CloudServices => lab::Target::CloudServices,
    })
}

/// The run manifest's version, as written, when the file at `manifest` declares one this build
/// doesn't read. Only that field is read.
fn stale_version(manifest: &Path) -> Option<serde_json::Value> {
    #[derive(serde::Deserialize)]
    struct Declared {
        manifest_version: Option<serde_json::Value>,
    }
    let text = std::fs::read(manifest).ok()?;
    let found = serde_json::from_slice::<Declared>(&text).ok()?.manifest_version?;
    serde_json::from_value::<ManifestVersion>(found.clone()).is_err().then_some(found)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn only_a_declared_version_this_build_doesnt_read_is_stale() {
        let dir = std::env::temp_dir().join(format!("cyberctf-stale-{}", rand::random::<u32>()));
        std::fs::create_dir_all(&dir).unwrap();
        let file = dir.join("run.json");
        let current = serde_json::to_value(ManifestVersion).unwrap();
        let read = |text: &str| {
            std::fs::write(&file, text).unwrap();
            stale_version(&file)
        };
        assert_eq!(read(r#"{"manifest_version": 0, "generator": {"name": "isoloom"}}"#), Some(serde_json::json!(0)));
        let newer = current.as_u64().unwrap() + 1;
        assert_eq!(read(&format!(r#"{{"manifest_version": {newer}}}"#)), Some(newer.into()), "a newer launcher's, after a downgrade");
        assert_eq!(read(&format!(r#"{{"manifest_version": {current}, "target": "docker"}}"#)), None, "this build's");
        assert_eq!(read("not a manifest"), None, "not one at all: the runner says what is wrong");
        assert_eq!(read("{}"), None, "no version: the runner says what is wrong");
        assert_eq!(stale_version(&dir.join("missing.json")), None);
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// `fut`, given 5 s.
    async fn in_time<F: Future>(fut: F) -> std::result::Result<F::Output, tokio::time::error::Elapsed> {
        tokio::time::timeout(std::time::Duration::from_secs(5), fut).await
    }

    /// Lab `n`'s folder under `root`, and its run manifest's path.
    fn lab_in(root: &Path, n: &str) -> (PathBuf, PathBuf) {
        let dir = root.join(n);
        (dir.join("run.json"), dir)
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 1)]
    async fn a_lab_being_generated_again_holds_up_no_other_lab_nor_a_thread() {
        // Regression: one process-wide lock served every lab, so one lab's regeneration held up
        // every other lab's status read; then a read waiting on its own lab's held the thread it
        // ran on, every other task on it stalled meanwhile.
        let root = std::env::temp_dir().join(format!("cyberctf-regen-{}", rand::random::<u32>()));
        let ((a_manifest, a), (b_manifest, b)) = (lab_in(&root, "a"), lab_in(&root, "b"));
        let held = lab_lock(&a);
        let a_busy = held.lock().await;
        assert!(matches!(in_time(current(&b_manifest, &b, Some(lab::Target::Docker))).await, Ok(Ok(()))), "lab b waited on lab a");
        // A read of lab a waits for it on the only worker, which still runs other tasks. Watched
        // from this thread, with no timer of the runtime's: a held worker would drive none.
        let waiting = tokio::spawn(async move { current(&a_manifest, &a, Some(lab::Target::Docker)).await });
        std::thread::sleep(std::time::Duration::from_millis(100));
        let (sent, other) = std::sync::mpsc::channel();
        tokio::spawn(async move { sent.send(7) });
        let ran = other.recv_timeout(std::time::Duration::from_secs(2));
        let early = waiting.is_finished();
        drop(a_busy);
        assert_eq!(ran, Ok(7), "the worker was held while the read waited");
        assert!(!early, "the read went on while its lab's generation was held");
        assert!(matches!(in_time(waiting).await, Ok(Ok(Ok(())))));
        let a = root.join("a");
        assert!(Arc::ptr_eq(&lab_lock(&a), &held), "one lock per lab, the same each time");
        assert!(!Arc::ptr_eq(&lab_lock(&b), &held));
    }

    #[test]
    fn a_runs_target_is_the_isoloom_target_of_the_same_name_but_a_helper_vms() {
        use isoloom_manifest::Target as Run;
        for run in [Run::Docker, Run::Vagrant, Run::Proxmox, Run::Esxi, Run::CloudDocker, Run::CloudVm, Run::CloudServices] {
            assert_eq!(serde_json::to_value(lab_target(run)).unwrap(), serde_json::to_value(run).unwrap(), "{run:?}");
        }
        assert_eq!(lab_target(Run::DockerVm), None, "Isoloom no longer generates a helper VM");
    }

    /// A lab an earlier version ran in a helper VM, with a run manifest of `version`: its folder
    /// (helper-VM mark on VirtualBox), its manifest's path.
    fn left_in_a_helper_vm(version: &serde_json::Value) -> (crate::testing::TempDir, PathBuf) {
        let dir = crate::runtime::test_support::write_lab(
            "version: 1\nname: t\nnetworks: { lab: { cidr: 10.70.0.0/24 } }\nmachines:\n  web: { os: debian@12, app: { image: nginx, steps: [{ run: web.sh }] }, networks: { lab: 10 } }\n",
        );
        std::fs::write(dir.join("web.sh"), "true\n").unwrap();
        crate::runtime::paths::mark_local_vm(&dir, Some(crate::runtime::providers::Provider::Virtualbox)).unwrap();
        let manifest = lab::docker_vm_dir(&dir).join("run.json");
        std::fs::create_dir_all(manifest.parent().unwrap()).unwrap();
        std::fs::write(&manifest, serde_json::json!({ "manifest_version": version, "target": "docker-vm" }).to_string()).unwrap();
        (dir, manifest)
    }

    #[tokio::test]
    async fn a_helper_vm_this_version_reads_is_left_as_it_is_to_be_stopped() {
        let (dir, manifest) = left_in_a_helper_vm(&serde_json::to_value(ManifestVersion).unwrap());
        let before = std::fs::read(&manifest).unwrap();
        current(&manifest, &dir, None).await.unwrap();
        assert_eq!(std::fs::read(&manifest).unwrap(), before, "read as it is: its run can be stopped and removed");
        assert!(crate::runtime::paths::local_vm(&dir).is_some(), "still the helper VM's run until it stops");
        assert!(!lab::docker_manifest(&dir).exists() && !lab::vagrant_dir(&dir, crate::runtime::Runtime::Vm).exists(), "nothing else generated");
    }

    #[tokio::test]
    async fn a_helper_vm_this_version_cant_read_moves_the_lab_to_its_true_form_and_says_what_is_left() {
        use crate::platform::exec::fake::{Tools, fail, ok};
        for (docker, form) in [(true, lab::Target::Docker), (false, lab::Target::Vagrant)] {
            let (dir, manifest) = left_in_a_helper_vm(&serde_json::json!(0));
            let _tools = Tools::new(move |program, args| match (program, args) {
                ("docker", ["version", ..]) if docker => ok("linux"),
                ("docker", _) => fail("Cannot connect to the Docker daemon"),
                _ => ok(""),
            });
            let err = current(&manifest, &dir, None).await.unwrap_err().to_string();
            assert!(err.starts_with(EARLIER_FILES) && err.contains("inside a VM") && err.ends_with(ADD_AGAIN), "{err}");
            assert_eq!(true_form(docker), form);
            let generated = match form {
                lab::Target::Docker => lab::docker_manifest(&dir),
                _ => lab::vagrant_dir(&dir, crate::runtime::Runtime::Vm).join("run.json"),
            };
            assert!(generated.is_file(), "{form:?}: the lab's files in its true form");
            assert_eq!(crate::runtime::paths::local_vm(&dir), None, "{form:?}: its next start is that form");
        }
    }
}
